insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place)
values
(E'https://matcha-jp.com/jp/24195', E'ja', 47, E'沖縄旅行のモデルコース！2泊3日で回れるコースを紹介', E'沖縄には観光地が数多くありますが、多すぎてどこに行こうか迷う人もいるでしょう。本記事では、2泊3日で沖縄旅行ができるモデルコースをご紹介します。各スポットの特徴もお伝えするので、参考にしてくださいね。\n\n沖縄の観光名所は本当に数多くありますが、だからこそどこに行こうか迷う人もいるのではないでしょうか？\n\nまた、車がないと移動しづらい環境のため、効率よく回る方法も知りたいところですよね。\n\nそこでこの記事では、2泊3日という短い期間でも効率よく観光できるモデルコースをご紹介します。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225246.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225247.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225248.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225249.webp"]'::jsonb, E'2025-02-20'::timestamptz, E'沖縄市'),
(E'https://matcha-jp.com/jp/23227', E'ja', 47, E'宮古島で食べたいグルメランキング5選！宮古そばや島おでんの人気店ガイド', E'この記事では「宮古そば」「宮古牛」「アグー豚」「島おでん」「島ダコ」など沖縄・宮古島の絶品ご当地グルメをランキング形式で紹介します。観光客はもちろん地元民にも愛されるおすすめのお店です。地元のグルメ情報を事前にチェックして、宮古島の食を余さず堪能しましょう。\n\n美しい自然に恵まれた沖縄・宮古島には、庶民的なB級グルメから沖縄の新鮮な食材を使った名物料理までさまざまなグルメがあります。\n\nそこでこの記事では、夜ご飯やランチにぴったりな宮古島のご当地グルメと、ぜひ訪れたいおすすめのお店をまとめて紹介します。\n\n▼宮古島を味わい尽くす！名物料理と絶品B級グルメ ▼宮古島の5大グルメとは？ ▼1位.宮古そば', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215063.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215064.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215065.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215066.webp"]'::jsonb, E'2024-12-13'::timestamptz, E'宮古島'),
(E'https://matcha-jp.com/jp/6875', E'ja', 47, E'【2026】沖縄の開花予報と桜まつり5選！日本一早く咲く桜を楽しもう', E'一年中温暖な気候で、きれいなビーチが多く、リゾート地として人気のある沖縄県。けれど魅力はそれだけではありません。日本一桜が早く咲くのです！ 沖縄の桜は1月中旬ごろから咲き始め、1月下旬には見ごろを迎えます。そんな沖縄の桜を見にいきたくなる、桜まつりを5つ紹介します。\n\n九州よりさらに南西にある、沖縄県。1年を通して温暖な気候で、きれいなビーチが多く、マリンアクティビティが盛んなことでも有名です。日本人だけでなく、訪日観光客からも人気のリゾート地。\n\n1つ目は、桜の開花が日本一早いこと！ 暖かい気候の沖縄では、桜が1月中旬ごろから咲き始めるため、日本で1番早く桜が咲くのです。\n\n2つ目は、桜の種類が本州とは異なること。本州では、ソメイヨシノがよくみられますが、沖縄はカンヒザクラが多いのです。カンヒザクラはソメイヨシノに比べ、濃いピンク色で下向きに咲きます。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/14-68105.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/14-68107.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/07-67657.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/07-67658.webp"]'::jsonb, E'2018-12-06'::timestamptz, E'沖縄市')
on conflict (url, lang) do update set
prefecture_code = excluded.prefecture_code,
title = excluded.title,
body = excluded.body,
images = excluded.images,
published_at = excluded.published_at,
place = excluded.place;
